async function section(titleTxt, subtitle, items){
  const sec=AF('section_'+titleTxt,'VERTICAL',10,[0,0,0,0]);
  const hdr=AF('hdr','HORIZONTAL',8,[0,0,0,0]); hdr.counterAxisAlignItems='CENTER';
