  hdr.appendChild(T(subtitle,12,'Regular',SUB));
  sec.appendChild(hdr);
  const grid=AF('grid','HORIZONTAL',10,[0,0,0,0]); grid.layoutWrap='WRAP'; grid.counterAxisSpacing=10;
  for(const it of items){
    const n=addOn.createInstance(); n.name='AddOn_'+it[0]; n.resize(165,60);
    const img=n.findOne(x=>x.type==='RECTANGLE');
    const label=n.findOne(x=>x.type==='TEXT');
    if(label) label.characters=it[0]+'  '+it[1];
    const toggle=n.findAll(x=>x.type==='FRAME').filter(x=>x!==n)[0];
    if(img) img.fills=S(it[2]);
    if(toggle){ toggle.fills=S(it[3]==='on'?RED:PILL); if(toggle.children[0]) toggle.children[0].fills=S(it[3]==='on'?WHITE:SUB); }
    grid.appendChild(n);
  }
  sec.appendChild(grid); grid.layoutSizingHorizontal='FILL';
  content.appendChild(sec); sec.layoutSizingHorizontal='FILL';
}
