async function bubble(side,txt,time){
  const row=AF('msg_'+(side==='bot'?'bot':'user'),'HORIZONTAL',8,[0,0,0,0]);
  row.primaryAxisAlignItems=side==='bot'?'MIN':'MAX'; row.counterAxisAlignItems='MIN';
  const col=AF('col','VERTICAL',4,[0,0,0,0]); col.counterAxisAlignItems=side==='bot'?'MIN':'MAX';
  const b=AF('bubble','VERTICAL',0,[10,14,10,14]);
  b.fills=S(side==='bot'?WHITE:RED); b.cornerRadius=16;
  if(side==='bot'){b.strokes=S(LINE); b.strokeWeight=1;}
  const t=T(txt,13,'Regular',side==='bot'?INK:WHITE,20); b.appendChild(t);
  b.resize(Math.min(272,Math.max(90,t.width+28)),b.height); t.layoutSizingHorizontal='FILL'; t.textAutoResize='HEIGHT';
  col.appendChild(b);
  col.appendChild(T(time,10,'Regular',SUB));
  if(side==='bot'){
    const av=(await figma.getNodeByIdAsync('2008:25')).clone(); av.rescale(30/120);
    row.appendChild(av); row.appendChild(col);
  } else { row.appendChild(col); }
  msgs.appendChild(row); row.layoutSizingHorizontal='FILL';
}
